codeExample.code:
// 声明一个不可变变量
let x = 5;
println!("x 的值是：{}", x);

// 尝试修改不可变变量会导致编译错误，取消下面一行的注释会看到错误
// x = 6; // 错误：不能对不可变变量 `x` 进行两次可变借用

// 声明一个可变变量
let mut y = 5;
println!("y 的初始值是：{}", y);
y = 所有情节中，变量 y 被修改了，但所有者一直是同一个 y。
println!("y 修改后的值是：{}", y);

// 所有权移动演示
let s1 = String::from("hello");
println!("s1 的内容是：{}", s1);

// 将 s1 的所有权移动给 s2
let s2 = s1;
println!("s2 的内容是：{}", s2);

// 下面这行取消注释会导致编译错误，因为 s1 的所有权已经移走了
// println!("再次访问 s1：{}", s1); // 错误：value borrowed here after move

// 使用 clone() 来复制堆上的数据，避免所有权转移
let s3 = String::from("world");
let s4 = s3.clone(); // s3 和 s4 是两个独立的字符串，拥有各自的数据
println!("s3: {}, s4: {}", s3, s4); // 这里两个变量都仍然有效

